data.transform:
(  
  $calendars := [$state.context.LOCAL.calendars];  
  /*
    $getDurationOfEvent - Returns the duration of an event
    $event - Fuuz Calendar Event Object
    @returns - Float
  */
  $getDurationOfEvent := function($event) {
    (       
      $moment($moment($event.end)).diff($moment($event.start))
    )
  };

  /* 
    $sliceArrayAfter - Returns a newly sliced array removing up until $firstIndex
    $arr - Array | Array to Slice
    $firstIndex - Integer | First Index to Retain
    $returns Array
  */
  $sliceArrayAfter := function($arr,$firstIndex) {
    $arr[[$firstIndex..$count($arr)]]
  };

  /*
    $getRemainingDuration - Returns the remaining duration in MS after the durationUsed was applied
    $totalDuration - Float
    $durationUsed - Float
    @returns - Float
  */
  $getRemainingDuration := function($totalDuration, $durationUsed) {
    (
      $totalDuration - $durationUsed      
    )
  };

  /* 
    $getEventsInRange - Returns events that are the same or before the $earliestStart
    $events - Array<Object> | $getAvailabilityBetween Calendar Events (Not Full Calendar Events)
    $earliestStart - Date | The start of the date range
    @returns - Array<Object>
  */
  $getEventsInRange := function($events,$earliestStart) {
    (
      $earliestStart := $moment($earliestStart);
      $filter([$events],function($v){
        (
          $start := $moment($v.start);
          $end := $moment($v.end);

          $start.isSameOrAfter($earliestStart)
        )
      })
    )
  };

  /* 
    $getEventsByConstraints - Returns events that are within the constraints provided
    $availability - Array<Object> | The full list of $getAvailabilityBetween Calendar Events (Not Full Calendar Events)
    $schedulingGroup - Object | The Scheduling Group you are trying to schedule
    @returns - Array<Object>
  */
  $getEventsByConstraints := function($availability,$schedulingGroup) {
    (
      $avail := $availability[id = $schedulingGroup.targetCalendarId];
      $getEventsInRange($avail.calendar,$schedulingGroup.constraints.earliestStart);
    )
  };

  /* 
    $sliceEventsByEarliestStart - Maps over the $events and slices events.
    $events - Array | $getAvailabilityBetween Calendar Events (Not Full Calendar Events)
    $schedulingGroup - Object | The Scheduling Group you are trying to schedule
    @returns - Array<Object>
  */
  $sliceEventsByEarliestStart := function($events,$schedulingGroup) {
    (
      $eventsAfter := $events.(
        $event := $;
        $earliestStartM := $moment($schedulingGroup.constraints.earliestStart);
        $eventStartM := $moment($event.start);
        $eventEndM := $moment($event.end);

        $earliestStartM.isBetween($eventStartM,$eventEndM) ? 
        (
          {
            /* New Event (This is technically the initial event updated. However because the order matters in the availability. We create a new event for this and add it to the start) */
            "newEvent": $merge([
              $event,
              {
                "id": $cuid(),
                "start": $eventStartM,
                "end": $earliestStartM
              }
            ]),
            /* Updated Event */
            "updatedEvent": $merge([
              $event,
              {
                "start": $earliestStartM,
                "end": $eventEndM
              }
            ])
          }
        )
        /* 
          If the earliestStart isn't between the events we just return undefined. 
          This function will only be used to add/update events in $avail to leave the slot that wasn't available
          To this job to be available to another job that could come along with an earlier start.
        */
      );
    )
  };

  /* 
    $updateCalendarEventsForEarliestStart - Updates Calendar Events Array of Objects with the newly created events and updates the prior event to shift it.
    $schedulingGroup - Object<SchedulingGroup> | A Scheduling Group Object
    $newEvents - Object {"newEvent": Object, "updatedEvent": Object}
    @returns - Array<Object> | Fuuz Calendars
  */
  $updateCalendarEventsForEarliestStart := function($calendars,$schedulingGroup,$newEvents) {
    (      
      $isNilOrEmpty($newEvents.updatedEvent) or $isNilOrEmpty($newEvents.newEvent) ? $calendars : (
        $calendars~>| $[id = $schedulingGroup.targetCalendarId] | (
          $curCalendar := calendar;

          $updatedCalendarEvents := [
            $newEvents.newEvent,
            $curCalendar~>| $[id = $newEvents.updatedEvent.id] | {
              "start": $newEvents.updatedEvent.start,
              "end": $newEvents.updatedEvent.end
            }|
          ];
          {
            "calendar": [
              /* We don't actually know if the newEvent is the furthest out in the list. So we're forced to re-sort the events */              
              $sort(
                $updatedCalendarEvents,
                function($l, $r) {
                  $moment($l.start).isAfter($moment($r.start))
                }
              )
            ]
          }
        )|
      )
    )
  };

  /* 
    $availObj - Object | A singular $getAvailabilityBetween object
    $days - Integer | The number of days we will extend the end date out. Defaults to 1 Day if not provided
  */
  $updateSchedulingRange := function($availObj, $days) {
    (
      $days := $coalesce([$days,1]);

      $availObj~>| $.schedulingRange | {
        "start": $moment(end),
        "end": $moment(end).add($days,'days')
      }|;
    )
  };

  /*
    $extendAvailability - Given an existing availability range will automatically extend the results by 1 day.
    $availability - Array<Object> | Calendar Availability Events
    $schedulingGroup - Object | Scheduling Group object
  */
  $extendAvailability := function($availability,$schedulingGroup) {
    (
      /* This is filtered down by the calendarId provided */
      $schedulingRange := $updateSchedulingRange($availability[id = $schedulingGroup.targetCalendarId]).schedulingRange;
      $targetCalendar := $calendars[calendar.id = $schedulingGroup.targetCalendarId];
      $availabilityCalendars := $calendars[calendar.id in $schedulingGroup.availabilityCalendarIds];      
      $newEvents := $getAvailabilityBetween(
        $moment($schedulingRange.start),
        $moment($schedulingRange.end),
        $mergeDeep([$targetCalendar, $availabilityCalendars])
      )~>| $ | {"id": $cuid() },["events"] |;

      $availability~>| $[id = $schedulingGroup.targetCalendarId] | {
        "schedulingRange": $schedulingRange,
        "calendar": $append([calendar],[$newEvents])
      }|;
    )
  };

  /* 
    $squashEvent - If this function finds an adjacent event that has the same end as the $newEvent start it will be squashed into a single event.
    $currentEvents - Array<Object> | A list of the current events
    $newEvent - Object | The new event to insert
  */
  $squashEvent := function($currentEvents,$newEvent) {
    (
      $lastEvent := $currentEvents[-1];

      $isNilOrEmpty($newEvent)        
        or 
      $not($lastEvent.groupEventType = $newEvent.groupEventType) 
        or
      $not($moment($lastEvent.end).isSame($newEvent.start,"minute"))
      ? [$currentEvents,$newEvent]
      : $currentEvents~>| $[-1] | { "end": $newEvent.end, "durationMs": $getDurationOfEvent({"start": start, "end": $newEvent.end }) } |
    )
  };

  /* 
    $getTargetCalendar - A simple helper function that directs you to the correct calendar you are targeting
    $availability - Array<Object> | A list of calendar availability objects
    $schedulingGroup - Object | The scheduling group you are scheduling
  */
  $getTargetCalendar := function($availability,$schedulingGroup) {
    $availability[id = $schedulingGroup.targetCalendarId]
  };

  /* 
    $shouldRejectSchedule - Based on the groupEventType we know whether we should reject the schedule being asked for or not. 
      Rejecting means that we will move forward to the future to see if there's somewhere else we can schedule.
      This code is always validating against the results from $convertGroupEventType which means the even might not actually be "allocated" but is considered allocated based on the logic.
    $event - Object | Calendar event object
  */
  $shouldRejectSchedule := function($event) {
    $event.derivedGroupEventType in ["allocated"] ? true
  };

  /* 
    $shouldFailSchedule - Based on the constraints provided (currently only mustEndBy is supported) we indicate if it's possible to schedule the event within the constraints. If not, we fail it and write it out as error.
    $schedulingGroup - Object | The scheduling group you are scheduling
    $eventEndDateTime - DateTime | The events end DateTime
  */
  $shouldFailSchedule := function($schedulingGroup,$events) {
    (
      /* The logic here is to take all of the events and pick the first event and last event. That will tell us whether it's within bounds or not. */
      $eventStartDateTime := $events[0].start;
      $eventEndDateTime := $events[-1].end;

      ($isNilOrEmpty($schedulingGroup.constraints.mustEndBy) and $isNilOrEmpty($schedulingGroup.constraints.mustStartBy)) ? false :
      $moment($eventEndDateTime).isAfter($schedulingGroup.constraints.mustEndBy) ? {"error": true, "message": "Failed to schedule because it wouldn't complete before: " & $schedulingGroup.constraints.mustEndBy } :
      $moment($eventStartDateTime).isAfter($schedulingGroup.constraints.mustStartBy) ? {"error": true, "message": "Failed to schedule because it wouldn't start before: " & $schedulingGroup.constraints.mustStartBy } : false
    )
  };

  /* 
    $shouldDecrementDuration - When scheduling events we have some cases where we don't actually decrement the duration but instead create an informational space on the calendar.
    $event - Object | Calendar Event
  */
  $shouldDecrementDuration := function($event) {
    (
      $event.derivedGroupEventType in ["available"];
    )
  };

  /* 
    $isInsideFirmWindow - This function will check the events end date to see if it's within the Firm Window. This will change which event type we create.
  */
  $isInsideFirmWindow := function($event) {
    $moment($event.end).isSameOrBefore($state.context.LOCAL.firmWindow.end)
  };

  /* 
    $convertGroupEventType - Remaps the incoming groupEventType to match it's meaning for the calendar. The "derivedGroupEventType" is what we use to indicate whether it's schedulable or not.
    $groupEventType - String | Calendar Availability Group Event Type (Maps 1-1 with calendar event type except for "unallocated")
  */
  $convertGroupEventType := function($event) {
    (
      $groupEventType := $event.groupEventType;
      $insideFirmWindow := $isInsideFirmWindow($event);

      $merge([
        $event,
        {          
          "derivedGroupEventType": (            
            $groupEventType in ["available"] ? "available" :
            $groupEventType in ["unavailable", "unallocated", "informational"] ? "unavailable" :
            $groupEventType in ["reserved"] and $insideFirmWindow ? "allocated" :
            $groupEventType in ["reserved"] and $not($insideFirmWindow) ? "available" :
            $groupEventType
         ),
         "groupEventType": (
            $groupEventType in ["available"] ? "allocated" :
            $groupEventType in ["unavailable", "unallocated","informational"] ? "informational" :
            $groupEventType in ["reserved"] and $insideFirmWindow ? "allocated" :
            $groupEventType in ["reserved"] and $not($insideFirmWindow) ? "allocated" :
            $groupEventType
          )
        }
      ]);
    )
  };

  /* 
      $scheduleEvent - Finds how much duration we can take from a calendar event and then schedules it. Updating the calendar event to remove the time that was used.
      $avail - Array<Object> | Fuuz Calendar Objects
      $schedulingGroup - Object | The scheduling group we're scheduling
      $type - String | The Type can either be "Setup" or "Production"
      @returns - Object | {"metadata": Object, "schedulingParams": Object, "avail": Object }
  */
  $scheduleEvent := function($avail,$schedulingGroup) {
    (  
       /* SETUP */
         /* We need to find our targetCalendar from availability. We need to figure out where we can start scheduling */
         $calendar := $getTargetCalendar($avail,$schedulingGroup);
         /* If the earliestStart is later than the start we need to slice the event into two events */
         $newEvents := $sliceEventsByEarliestStart($calendar.calendar,$schedulingGroup);
         /* We now need to overwrite $avail with the new calendar that includes the new event as well as the updated event for where the slice took place */
         $avail := $updateCalendarEventsForEarliestStart($avail,$schedulingGroup,$newEvents);                
         /* $getEventsByConstraints will return a list of events that start at the same time or after $schedulingParams.constraints.earliestStart */
         $availableEvents := $getEventsByConstraints($avail,$schedulingGroup);
       /* END SETUP */

       /* SCHEDULING START */
         /* Pick the first event. This will be in our range */
         $calendarEventIndex := $availableEvents[0].id;
         $pickedEvent := $availableEvents[id = $calendarEventIndex];
         $eventDuration := $getDurationOfEvent($pickedEvent);

         /* Lets see if the scheduling groups duration is greater than or equal to the eventDuration. If it is the entire event was consumed. If not we only use part of the event */
         $eventConsumed := $schedulingGroup.durationMs >= $eventDuration;
         $durationUsed := $eventConsumed ? $eventDuration : $schedulingGroup.durationMs;

         /* We will re-use this a few times, we need to know based on $durationUsed what is the new end of the event */
         $eventEndDateTime := ($moment($pickedEvent.start).add($durationUsed,'milliseconds'))[0];

         /* Define our new event and see if it will work or not */
         $newEvent := $durationUsed > 0 ? $convertGroupEventType({ "start": $pickedEvent.start, "end": $eventEndDateTime, "groupEventType": $pickedEvent.groupEventType, "durationMs": $durationUsed });
         $updatedEvents := $squashEvent(
           $schedulingGroup.events,
           $durationUsed > 0 ? $newEvent
         );

         $rejectEvent := $shouldRejectSchedule($newEvent);

         {
           "metadata": {
             "setupResults": $setupResults,
             "eventPicked": $pickedEvent,
             "newEvents": $newEvent,             
             "maxDuration": $eventDuration,
             "durationUsed": $durationUsed,
             "eventConsumed": $eventConsumed,
             "updatedEvents": $updatedEvents,
             "availableEvents": $availableEvents
           },
           "schedulingGroup": $merge(
             [
               $schedulingGroup,
               {                 
                 "endsAt": $eventEndDateTime,
                 /* If the calendar cannot fulfill this entire event, we will return the remaining durationMs here. */
                 "durationMs": $shouldDecrementDuration($newEvent) ? $getRemainingDuration($schedulingGroup.durationMs, $durationUsed) : $schedulingGroup.durationMs,
                 "constraints": $merge([
                   $schedulingGroup.constraints,
                   {
                     "earliestStart": $rejectEvent = true ? $pickedEvent.end
                   }
                 ]),
                 "events": [
                   /* The rest of the code around this will remove the availability  */
                   $filter($updatedEvents,function($v){$not($v.groupEventType = "informational")})
                 ]
               }
             ]
           ),
           "availability": (
               $avail~>| $[id = $schedulingGroup.targetCalendarId] | (  
                 $eventConsumed = false ? (
                   $~>| calendar[id = $calendarEventIndex] | {
                       "start": $eventEndDateTime
                   }|
                )
                :
                {
                  "calendar": [ $filter([calendar], function($v){ $not($v.id = $calendarEventIndex) }) ]
                }
             )|
           ),
           "reject": $rejectEvent,
           "fail": $filter($shouldFailSchedule($schedulingGroup,$updatedEvents),function($v) {$v.error})
         };
    )
  };

  $addErrors := function($schedulingGroup,$error,$removeEvents) {
    $schedulingGroup~>| $ | { "error": [error,$error] },$removeEvents = true ? ["events"] : []|
  };

  /* Recurse Parameters for debugging/extending loops */
  $maxLoops := 1000;
  $returnAcc := true;
  $returnAvail := false;

  $recurse := function($availability,$fullAvail,$schedulingGroup,$loopCounter,$acc) {
    $loopCounter > $maxLoops ? {
      "type": "Loop Counter Over " & $maxLoops,
      "results": $addErrors($schedulingGroup,{"error": true, "message": "Cannot Schedule, Loop Counter exceeded maxLoops of: " & $maxLoops},false),
      "availability": $availability,
      "fullAvail": $fullAvail,
      "acc": $returnAcc ? $acc
    } :
    $isNilOrEmpty($availability) ? {
      "type": "No Availability",
      "results": $addErrors($schedulingGroup,{"error": true, "message": "No Availability Provided to the request, cannot schedule"},false),
      "availability": $availability,
      "acc": $returnAcc ? $acc      
    } :
    $isNilOrEmpty($schedulingGroup) ? {
      "type": "Scheduling Group is not defined",
      "results": $addErrors($schedulingGroup,{"error": true, "message": "Scheduling Group is not defined, cannot schedule"}),
      "availability": $availability,
      "acc": $returnAcc ? $acc
    } :
    $schedulingGroup.durationMs <= 0 ? {
      "type": "Completed Scheduling Group (Duration <= 0)", 
      "results": $schedulingGroup,
      "availability": $availability,
      "acc": $returnAcc ? $acc
    } :
    /* We only want to enter the below code block IF the duration is greater than 0 and there are still events to schedule. */
    $schedulingGroup.durationMs > 0 ?
    (
      /* If we have availability we can schedule, lets schedule it. */
      $count($getEventsByConstraints($availability,$schedulingGroup)) > 0 ? (
        $result := $scheduleEvent($availability,$schedulingGroup);
        /* 
          The scheduleEvent function will tell us if we should reject the scheduling and restart from the top with an adjusted earliestStart date.
        */
        $result.reject = true ?
          $recurse(
            [$fullAvail],
            [$fullAvail],
            $state.context.LOCAL.schedulingGroups[$state.context.LOCAL.pagination.curIndex]
              ~>| $.constraints | { "earliestStart": $result.schedulingGroup.constraints.earliestStart }|
              ~>| $ | { "reschedulingAttempts": $schedulingGroup.reschedulingAttempts + 1}|,
            $loopCounter + 1,
            [$acc,$result]
          )
          :
        /* 
          The scheduleEvent function will also tell us if we need to fail scheduling this group. This means there is no way we can continue from this point forward.
        */
        $count($result.fail.error) > 0 ? {
          "type": "Failed to schedule",          
          "results": $addError($schedulingGroup,$result.fail,true),
          "availability": $fullAvail,
          "acc": $returnAcc ? [$acc,$result]
        }
        :
        $recurse(
          [$result.availability],
          [$fullAvail],
          $result.schedulingGroup,
          $loopCounter + 1,
          [$acc,$result]
        )
      )
      :
      (
        /* Otherwise we need extend the availability and loop back */        
        $recurse(
          $extendAvailability($availability,$schedulingGroup),
          $extendAvailability($fullAvail,$schedulingGroup),
          $schedulingGroup,
          $loopCounter + 1,
          [
            $acc
          ]
        )
      )
    )
    : 
    {
      "type": "Completed Scheduling Group (Default Case)", 
      "results": $schedulingGroup,
      "availability": $availability,
      "acc": $returnAcc ? $acc
    }
  };

  $recurse(
    $state.context.LOCAL.availability,
    $state.context.LOCAL.availability,
    $state.context.LOCAL.schedulingGroups[$state.context.LOCAL.pagination.curIndex],
    0,
    []
  );  
)

$state.context~>| $ | {
  "LOCAL": LOCAL~>| $ | (
    $schedulingGroups := [$state.context.LOCAL.schedulingGroups]~>| $[$state.context.LOCAL.pagination.curIndex] | $$.results[0] |
       ~>| $[($$.results[0].id in [dependsOnIds]) and durationMs > 0].constraints | {
          "earliestStart": $$.results[0].error.error = true ? undefined : $moment(earliestStart).isAfter($moment($$.results[0].endsAt)) ? earliestStart : $$.results[0].endsAt
      }|;

    { 
      "schedulingError": $count($flatten([$schedulingGroups.error[error = true]])) > 0,
      "schedulingGroups": $schedulingGroups,
      "availability": [$$.availability],
      "pagination": pagination~>| $ | {
        "curIndex": $state.context.LOCAL.pagination.curIndex + 1
      }|
    }
  )|
}|

