data.transform:
(
	$now := $moment();
	$isValidMustStartBy := function($schedulingGroup) {
		(
			$constraints := $schedulingGroup.constraints;
			$isNilOrEmpty($constraints.mustStartBy)
				? undefined
				: $moment($constraints.earliestStart)
					.isBefore($constraints.mustStartBy)
					? undefined
					: {
						"error": true,
						"message": "earliestStart is after mustStartBy"
					}
		)
	};

	$isValidMustEndBy := function($schedulingGroup) {
		(
			$constraints := $schedulingGroup.constraints;
			$isNilOrEmpty($constraints.mustEndBy)
				? undefined
				: $moment($constraints.earliestStart)
					.isAfter($constraints.mustEndBy)
					? {
						"error": true,
						"message": "earliestStart is after mustEndBy",
						"info": $constraints
					}
					: $moment($constraints.earliestStart)
						.add($schedulingGroup.durationMs, "ms")
						.isAfter($constraints.mustEndBy)
						? {
							"error": true,
							"message": "earliestStart + durationMs will exceed mustEndBy",
							"info": $constraints
						}
						: undefined
		)
	};

	$isValidEarliestStart := function($schedulingGroup) {
		(
			$constraints := $schedulingGroup.constraints;
			$currentDateTime := $moment();
			$moment($constraints.earliestStart)
				.diff($currentDateTime, "minutes")
				> -5
				? undefined
				: {
					"error": true,
					"message": "earliestStart is more than 5 minutes in the past. This value should be in the future."
				}
		)
	};

	$state.context.LOCAL.schedulingGroups
		~> |constraints|{
			"earliestStart": $moment(earliestStart).isBefore($now)
				? $now.toISOString()
				: earliestStart
		}|
		~> |$|(
			$schedulingGroup := $;
			{
				"error": [
					$isValidMustStartBy($schedulingGroup),
					$isValidMustEndBy($schedulingGroup),
					$isValidEarliestStart($schedulingGroup)
				]
			}
		)|
)

