data.transform:
(
	$availCalendarIds := $uniq([$state
		.context
		.LOCAL
		.schedulingGroups
		.availabilityCalendarIds]);

  $availCalendars := [
		$state.context.LOCAL.calendars.calendar[id in $availCalendarIds]
	];

	$schedulingErrors := {
		"errors": [
			$filter(
				[$availCalendars],
				function($v) { $count([$v.calendarEvents]) = 0 }
			)
				.{
					"error": true,
					"message": $join(
						["Calendar:", name, "has no calendar events defined"],
						" "
					),
          "calendarId": id
				},
			$filter(
				[$availCalendars],
				function($v) {
					$count($v.calendarEvents[eventJson.duration = 0]) > 0
				}
			)
				.{
					"error": true,
					"message": $join(
						[
							"Calendar:",
							name,
							"includes 0ms Calendar Event(s):",
							$join(
								[calendarEvents[eventJson.duration = 0].title],
								","
							)
						],
						" "
					),
          "calendarId": id
				}
		]
	};

	$state.context.LOCAL.schedulingGroups
		~> | $ |(
			$schedulingGroup := $;
			{
				"error": [
					$schedulingErrors.errors[calendarId in $schedulingGroup.availabilityCalendarIds]
				]
			}
		)|
)
